const items = $input.all();
const results = [];
for (const item of items) {
  const t = item.json;
  const val = Number(t.valorTotalEstimado || t.valor || 0);
  if (val < 10000) continue;
  const estimatedProfit = val * 0.25;
  let score = 70;
  let priority = 'NORMAL';
  if (t.modalidadeNome === 'Dispensa de Licitação' || val >= 100000) { score = 90; priority = 'HIGH'; }
  results.push({
    json: {
      category: 'public_tender',
      title: `Licitação PNCP: ${t.objetoContratacao || t.titulo || 'Edital'}`,
      description: `Órgão: ${t.orgaoEntidade?.razaoSocial || 'Órgão Público'} | Modalidade: ${t.modalidadeNome || 'Pregão'} | Lucro Est. (25%): R$ ${estimatedProfit.toLocaleString('pt-BR')}`,
      opportunity_price: val,
      original_price: val,
      net_profit_estimate: Number(estimatedProfit.toFixed(2)),
      location: t.unidadeOrgao?.municipioNome || 'Nacional',
      source_name: 'PNCP / Comprasnet',
      source_url: t.linkSistemaOrigem || 'https://pncp.gov.br',
      evaluation_score: score,
      priority
    }
  });
}
return results;
